UPDATE public.junior_cloze SET questions='[{"q":"1","answer":"C","options":["free","lazy","busy","quiet"],"explanation":"keep sb busy 使某人忙碌;作业、科目多,所以学生很忙。"},{"q":"2","answer":"B","options":["friends","subjects","clubs","games"],"explanation":"more homework and more subjects 更多作业和科目。"},{"q":"3","answer":"D","options":["mistake","promise","choice","schedule"],"explanation":"make a schedule 制定日程表。"},{"q":"4","answer":"D","options":["boring","funny","easy","important"],"explanation":"the most important tasks 最重要的任务。"},{"q":"5","answer":"B","options":["forget","decide","refuse","win"],"explanation":"decide how much time 决定需要多少时间。"},{"q":"6","answer":"D","options":["wrong","late","hard","wise"],"explanation":"it is wise to leave free time 留出空闲时间是明智的。"},{"q":"7","answer":"D","options":["happy","ready","clear","healthy"],"explanation":"all work and no play is not healthy 只学不玩不健康。"},{"q":"8","answer":"A","options":["follow","break","lose","miss"],"explanation":"follow your schedule 遵守日程表。"},{"q":"9","answer":"B","options":["proud","anxious","free","happy"],"explanation":"feel less anxious 不那么焦虑。"},{"q":"10","answer":"A","options":["trying","sleeping","playing","leaving"],"explanation":"keep trying 坚持努力。"}]'::jsonb WHERE id='25ec6279-2318-461e-9b3a-beeacf89b72b';
UPDATE public.junior_cloze SET questions='[{"q":"1","answer":"C","options":["happy","proud","worried","sure"],"explanation":"be worried about 为……担心。"},{"q":"2","answer":"C","options":["soon","well","often","early"],"explanation":"plays games too often 玩游戏太频繁。"},{"q":"3","answer":"D","options":["alone","aloud","away","online"],"explanation":"spends too much time online 花太多时间上网。"},{"q":"4","answer":"D","options":["refuse","forget","promise","recommend"],"explanation":"I recommend that you talk 我建议你和他谈谈。"},{"q":"5","answer":"B","options":["schedule","behaviour","title","plate"],"explanation":"talk about his behaviour 谈他的行为。"},{"q":"6","answer":"D","options":["afraid","ready","good","attracted"],"explanation":"be attracted to 被……吸引。"},{"q":"7","answer":"D","options":["useful","helpful","healthy","unhealthy"],"explanation":"too much time online is unhealthy 上网太久不健康。"},{"q":"8","answer":"B","options":["depend","focus","agree","win"],"explanation":"focus on other things 专注于别的事。"},{"q":"9","answer":"B","options":["force","encourage","stop","leave"],"explanation":"encourage him to try new hobbies 鼓励他尝试新爱好。"},{"q":"10","answer":"D","options":["agree","follow","believe","listen"],"explanation":"listen to sb 听某人的(只有 listen 能接 to you 表“听从”);agree/follow/believe 不接 to you。"}]'::jsonb WHERE id='6a4c346e-67e8-45bf-aeb9-cf3cdd639aee';
UPDATE public.junior_cloze SET questions='[{"q":"1","answer":"B","options":["home","last","night","school"],"explanation":"at last 终于。"},{"q":"2","answer":"B","options":["lucky","anxious","proud","happy"],"explanation":"because not very outgoing,所以有点 anxious(紧张)。"},{"q":"3","answer":"D","options":["idea","plan","lesson","impression"],"explanation":"make a good first impression 留下好的第一印象。"},{"q":"4","answer":"B","options":["easy","difficult","short","free"],"explanation":"but the teacher was kind 表转折,说明课 difficult(难)。"},{"q":"5","answer":"C","options":["song","game","story","word"],"explanation":"told us a funny story 讲了个有趣的故事。"},{"q":"6","answer":"C","options":["cried","slept","laughed","left"],"explanation":"funny story 让 everyone laughed(大笑)。"},{"q":"7","answer":"B","options":["angry","friendly","tired","busy"],"explanation":"classmates friendly and helpful 同学友好乐于助人。"},{"q":"8","answer":"A","options":["concentrate","depend","agree","win"],"explanation":"concentrate on 专注于;被打扰所以无法专注。"},{"q":"9","answer":"A","options":["confident","tired","angry","anxious"],"explanation":"傍晚比早晨更 confident(自信)。"},{"q":"10","answer":"C","options":["week","class","day","year"],"explanation":"tomorrow will be a great day 明天会是美好的一天。"}]'::jsonb WHERE id='7fbdcf07-e127-4189-9bac-35b21cee84c7';
UPDATE public.junior_cloze SET questions='[{"q":"1","answer":"B","options":["difficult","suitable","boring","angry"],"explanation":"be suitable for 对……合适。"},{"q":"2","answer":"D","options":["problem","mistake","question","choice"],"explanation":"a good choice 一个好选择。"},{"q":"3","answer":"C","options":["good","afraid","interested","ready"],"explanation":"be interested in 对……感兴趣。"},{"q":"4","answer":"A","options":["discuss","dance","grow","clean"],"explanation":"辩论社的人喜欢 discuss(讨论)不同话题。"},{"q":"5","answer":"D","options":["give","look","get","sign"],"explanation":"sign up for 报名参加。"},{"q":"6","answer":"B","options":["look","clean","give","put"],"explanation":"clean up the park 打扫公园。"},{"q":"7","answer":"B","options":["happy","anxious","proud","glad"],"explanation":"because I knew no one,所以感到 anxious(焦虑)。"},{"q":"8","answer":"C","options":["angry","lazy","friendly","boring"],"explanation":"其他成员很 friendly(友好),所以很快交到朋友。"},{"q":"9","answer":"C","options":["problems","mistakes","friends","clubs"],"explanation":"made some new friends 交到新朋友。"},{"q":"10","answer":"A","options":["use","waste","lose","miss"],"explanation":"use your free time well 善用空闲时间。"}]'::jsonb WHERE id='91d3eb8b-7c98-466c-8bbe-224da383a388';
UPDATE public.junior_cloze SET questions='[{"q":"1","answer":"A","options":["responsible","ready","famous","free"],"explanation":"be responsible for 对……负责。"},{"q":"2","answer":"C","options":["clubs","plants","parents","teams"],"explanation":"at home,help our parents 在家帮父母。"},{"q":"3","answer":"A","options":["behaviour","ballet","debate","schedule"],"explanation":"studies and behaviour 学业和行为。"},{"q":"4","answer":"A","options":["losing","finding","keeping","getting"],"explanation":"means losing their freedom 意味着失去自由。"},{"q":"5","answer":"D","options":["late","busy","easy","true"],"explanation":"but this is not true 但这不是真的。"},{"q":"6","answer":"C","options":["away","down","together","up"],"explanation":"go together 相伴而行。"},{"q":"7","answer":"A","options":["trust","leave","blame","force"],"explanation":"adults trust you more 大人更信任你。"},{"q":"8","answer":"A","options":["time","hand","foot","head"],"explanation":"finish homework on time 按时完成作业。"},{"q":"9","answer":"C","options":["week","year","day","hour"],"explanation":"in a single day 在一天之内。"},{"q":"10","answer":"D","options":["hide","run","fall","learn"],"explanation":"learn from them 从错误中学习。"}]'::jsonb WHERE id='b347d85b-72a9-495d-b256-2c09fcc222ed';
UPDATE public.junior_cloze SET questions='[{"q":"1","answer":"C","options":["holiday","present","challenge","mistake"],"explanation":"a real challenge 真正的挑战。"},{"q":"2","answer":"D","options":["doctor","driver","writer","adviser"],"explanation":"the school adviser 学校顾问。"},{"q":"3","answer":"A","options":["difficult","easy","free","short"],"explanation":"but I will work hard 表转折,说明科目 difficult。"},{"q":"4","answer":"B","options":["refused","recommended","forgot","stopped"],"explanation":"adviser recommended that I sign up 建议我报名。"},{"q":"5","answer":"B","options":["ballet","literature","football","weather"],"explanation":"advanced literature,because I like English 高级文学。"},{"q":"6","answer":"C","options":["afraid","ready","good","sorry"],"explanation":"be good at 擅长。"},{"q":"7","answer":"A","options":["activities","mistakes","problems","lessons"],"explanation":"extra-curricular activities 课外活动。"},{"q":"8","answer":"A","options":["enough","again","ago","instead"],"explanation":"play well enough 踢得够好。"},{"q":"9","answer":"C","options":["win","smile","quit","agree"],"explanation":"I will not quit 我不会放弃。"},{"q":"10","answer":"A","options":["improve","forget","lose","fail"],"explanation":"find a way to improve 找办法提高。"}]'::jsonb WHERE id='e7d38fd8-9830-4446-9708-6019518fc8a6';
