UPDATE public.junior_listening_exercises SET questions='[{"q":"What is Chen Lei''s problem?","type":"choice","answer":"B","options":["He never does sports.","He plays computer games too often.","He has no friends.","He reads too much."]},{"q":"How does the speaker feel about Chen Lei?","type":"choice","answer":"C","options":["Proud.","Angry.","Worried.","Bored."]},{"q":"What does the teacher say about teenagers and games?","type":"choice","answer":"D","options":["They should never play.","Games are good for study.","Only adults like games.","It is normal to be attracted to games."]},{"q":"Why is spending too much time online a problem?","type":"choice","answer":"B","options":["It costs no money.","It is unhealthy.","It is against the law.","It is too easy."]},{"q":"What does the teacher recommend?","type":"choice","answer":"B","options":["Playing more games.","Trying new hobbies.","Staying online longer.","Stopping school."]}]'::jsonb WHERE id='6bcee8b7-9828-46b5-a0d8-93c6a92a6450';
UPDATE public.junior_listening_exercises SET questions='[{"q":"What does Li Ming do every evening?","type":"choice","answer":"B","options":["Plays games.","Reviews his notes.","Watches TV shows.","Goes to a club."]},{"q":"How does Li Ming improve his pronunciation?","type":"choice","answer":"A","options":["By copying short videos.","By singing songs.","By reading novels.","By making mind maps."]},{"q":"What does Amy like to make?","type":"choice","answer":"B","options":["Word cards.","Mind maps.","Posters.","Schedules."]},{"q":"What do they decide to do?","type":"choice","answer":"D","options":["Join the same club.","Stop studying English.","Watch a film together.","Share their learning methods."]},{"q":"What does Amy think about working together?","type":"choice","answer":"C","options":["It is a waste of time.","It is too difficult.","It makes learning more fun.","It is boring."]}]'::jsonb WHERE id='946a8177-910a-4e95-ae7c-f164fcb6614d';
UPDATE public.junior_listening_exercises SET questions='[{"q":"Which two clubs is Sam choosing between?","type":"choice","answer":"C","options":["The Nature Club and the Music Club.","The Volunteer Club and the Art Club.","The Ballet Club and the Debate Club.","The Football Club and the Chess Club."]},{"q":"What does Sam enjoy doing?","type":"choice","answer":"D","options":["Dancing.","Growing plants.","Playing football.","Discussing different topics."]},{"q":"Which club does Adam suggest for Sam?","type":"choice","answer":"A","options":["The Debate Club.","The Ballet Club.","The Volunteer Club.","The Nature Club."]},{"q":"Which club did Adam join?","type":"choice","answer":"D","options":["The Debate Club.","The Ballet Club.","The Music Club.","The Volunteer Club."]},{"q":"What will Sam do today?","type":"choice","answer":"A","options":["Sign up for the Debate Club.","Join the Ballet Club.","Quit the club.","Help homeless people."]}]'::jsonb WHERE id='a637dc89-c94d-4497-bdfb-4632a5a79fc3';
UPDATE public.junior_listening_exercises SET questions='[{"q":"What happens as teenagers grow up?","type":"choice","answer":"D","options":["They have fewer duties.","They stop studying.","They leave home.","They become responsible for more things."]},{"q":"What are teenagers responsible for at school?","type":"choice","answer":"D","options":["Cleaning the school.","Teaching classes.","Cooking lunch.","Their own studies and behaviour."]},{"q":"What happens when you show you are responsible?","type":"choice","answer":"C","options":["You get more homework.","You lose free time.","Adults trust you more.","Friends stop liking you."]},{"q":"What example does the speaker give?","type":"choice","answer":"B","options":["Playing sports every day.","Finishing homework on time.","Going to bed early.","Joining a club."]},{"q":"What does the speaker say about becoming responsible?","type":"choice","answer":"A","options":["We can learn from our mistakes.","It happens in one day.","It is impossible.","It needs no effort."]}]'::jsonb WHERE id='c7bdefcd-3f0e-483e-a5e8-829c7989ab49';
UPDATE public.junior_listening_exercises SET questions='[{"q":"How did the speaker feel in the morning?","type":"choice","answer":"C","options":["Very angry.","Quite bored.","A little anxious.","Very proud."]},{"q":"Why did the speaker feel anxious?","type":"choice","answer":"A","options":["He is not very outgoing.","He was late.","He forgot his books.","He was ill."]},{"q":"What was the first maths class like?","type":"choice","answer":"C","options":["Easy but boring.","Short and noisy.","Difficult, but the teacher was kind.","Cancelled."]},{"q":"Why couldn''t the speaker concentrate in the afternoon?","type":"choice","answer":"C","options":["The class was too long.","He felt sick.","The boy next to him talked too much.","The room was cold."]},{"q":"How did the speaker feel by the evening?","type":"choice","answer":"B","options":["Tired and sad.","Much more confident.","Still anxious.","Angry with friends."]}]'::jsonb WHERE id='cd8274bf-084a-4314-a981-7c024a3ec6a4';
UPDATE public.junior_listening_exercises SET questions='[{"q":"How many camps does Max mention?","type":"choice","answer":"A","options":["Two.","Three.","One.","Four."]},{"q":"What can students learn at the adventure camp?","type":"choice","answer":"A","options":["Survival skills.","Cooking.","Dancing.","Painting."]},{"q":"Why does Cao Jing prefer the youth camp?","type":"choice","answer":"D","options":["It is cheaper.","It is nearer.","It is shorter.","She wants to improve her English."]},{"q":"What can they do at the international youth camp?","type":"choice","answer":"B","options":["Learn to make a fire.","Practise spoken English.","Live in the wild.","Grow plants."]},{"q":"Who will they meet at the youth camp?","type":"choice","answer":"A","options":["Students from different countries.","Only their classmates.","Famous actors.","Their teachers."]}]'::jsonb WHERE id='f98681ff-2a9a-4a03-93d4-6d835b84cce9';
